    // ── Enums ──────────────────────────────────────────────────────────────────

    public enum CharacterType { SONARA, AURELIUS, LYRON }

    public enum PlayerState { IDLE, WALK_UP, WALK_DOWN, WALK_LEFT, WALK_RIGHT }

    public enum Facing { LEFT, RIGHT }

